// NB-02 · spec: .qa/e2e/specs/nearby.md 1.2 · меняет данные reg1 → в finally share_location=false, nearby_opt_in=false.
import { test, expect } from '../../fixtures';
import { openRole, openWereHere, turnOff, dbState, tapWhenTop, isProfilePatch, consentTitle, enableBtn, shareSwitch, listTitle, emptyTitle } from './nearby-helpers';

test.use({ browserName: 'webkit' });

test.describe('היו כאן — משתמשים שהיו בקרבת מקום', () => {
  test.describe.configure({ timeout: 120_000 });
  test('без согласия — запрос 17.01e; «להפעיל» включает участие и шаринг без перезагрузки @iphone @data (#ab0123 #67c751 #ee51bb)', async ({ browser }) => {
    const reg1 = await openRole(browser, 'reg1');
    const p = reg1.page;
    try {
      await turnOff(reg1); // предусловие: согласия нет
      const st = await openWereHere(p, reg1.id);
      expect(st).toEqual({ nearby_opt_in: false, share_location: false });
      await expect(consentTitle(p)).toBeVisible();
      await expect(p.getByText('נשמור את המיקום שלך עד 7 שעות. אפשר לכבות בהגדרות')).toBeVisible();
      await expect(enableBtn(p)).toBeVisible();
      await expect(listTitle(p)).toHaveCount(0);

      const patch = p.waitForResponse(isProfilePatch);
      await tapWhenTop(p, enableBtn(p));
      const res = await patch;
      expect(res.ok()).toBeTruthy();
      expect(res.request().postDataJSON()).toMatchObject({ nearby_opt_in: true, share_location: true });
      await expect(listTitle(p).or(emptyTitle(p)).first()).toBeVisible(); // без перезагрузки
      await expect(shareSwitch(p)).toBeVisible();
      await expect(consentTitle(p)).toHaveCount(0);
    } finally {
      await turnOff(reg1);
    }
    expect(await dbState(reg1)).toEqual({ nearby_opt_in: false, share_location: false });
    await reg1.ctx.close();
  });
});
